import{_ as t,o as e,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Jewel -- Non-Functional Tests","description":"","frontmatter":{"title":"CDS Jewel -- Non-Functional Tests","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","非功能性测试","性能评估","分布式存储","开发流程"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Non-Functional_Tests.md","filePath":"posts/2015/CDS_Jewel_--_Non-Functional_Tests.md","lastUpdated":1780459816000}'),s={name:"posts/2015/CDS_Jewel_--_Non-Functional_Tests.md"};function n(p,l,a,r,_,u){return e(),i("div",null,[...l[0]||(l[0]=[o("<p>本次会议主要讨论了在Ceph开发过程中引入非功能性测试的方案，并提出了相应的技术实现。以下是对会议内容的详细总结：</p><p><strong>会议背景</strong></p><ul><li>会议介绍者是一位在UC Santa Cruz攻读博士、同时在Red Hat实习的学生，负责Ceph的非功能性测试项目。</li><li>非功能性测试是指评估系统整体质量而非特定行为的测试，如可扩展性、性能等。</li></ul><p><strong>项目目标</strong></p><ul><li>将非功能性测试纳入Ceph开发流程。</li><li>使用集成测试、基准测试和验证测试相结合的方法。</li><li>通过性能指标和验证断言来评估系统质量。</li></ul><p><strong>技术方案</strong></p><ul><li>利用cgroup资源限制来控制测试环境。</li><li>使用验证语言和验证引擎来定义和执行验证测试。</li><li>使用tautology作为基准测试工具。</li><li>开发maestro任务来部署和配置Ceph集群。</li><li>开发rattles任务来运行基准测试。</li><li>开发a verte任务来验证测试结果。</li></ul><p><strong>验证测试</strong></p><ul><li>定义验证语句来评估系统质量，例如可扩展性、性能、可用性等。</li><li>使用验证引擎来执行验证语句。</li><li>通过分析日志和性能指标来验证系统质量。</li></ul><p><strong>后续行动</strong></p><ul><li>开发验证语句。</li><li>完成tautology任务的开发。</li><li>集成验证测试到Ceph开发流程。</li></ul><p><strong>讨论要点</strong></p><ul><li>如何量化非功能性测试结果。</li><li>如何应对硬件非确定性。</li><li>如何定义验证测试。</li><li>如何将验证测试集成到Ceph开发流程。</li></ul><p><strong>其他</strong></p><ul><li>讨论了使用rattles、fio等工具进行基准测试的优缺点。</li><li>讨论了使用验证语言和验证引擎进行验证测试的可行性。</li></ul><p>本次会议强调了非功能性测试在Ceph开发中的重要性，并为后续工作提供了指导。通过引入非功能性测试，Ceph可以更好地保证其整体质量和性能。</p>",16)])])}const C=t(s,[["render",n]]);export{g as __pageData,C as default};
